Repair the source below and return one corrected complete TypeScript source file while preserving its exports. `ConversionHub` registers uniquely named synchronous transformers. Names are trimmed, nonempty, and duplicates throw `RangeError`. `convert(records)` must apply transformers in registration order to each record independently. Each transformer receives a fresh copy of the previous value, and each successful result contains a fresh copy, so inputs, plugin outputs, and returned records are not aliased through the hub. A thrown non-`Error` value is converted with `String`; an `Error` uses its message. Failure stops processing only that record, records remain in input order, and an empty input returns `[]`. Registration during a conversion affects only later conversions because the active transformer list is snapshotted.

```ts
export interface DataRecord {
  key: string;
  fields: Record<string, string>;
}

export interface Transformer {
  readonly name: string;
  transform(record: DataRecord): DataRecord;
}

export type ConversionResult =
  | { ok: true; record: DataRecord }
  | { ok: false; key: string; error: string };

export class ConversionHub {
  private readonly transformers: Transformer[] = [];

  register(transformer: Transformer): void {
    const name = transformer.name.trim();
    if (name.length === 0) throw new TypeError("transformer name must be nonempty");
    if (this.transformers.some((item) => item.name.trim() === name)) {
      throw new RangeError("duplicate transformer");
    }
    this.transformers.push(transformer);
  }

  convert(records: readonly DataRecord[]): ConversionResult[] {
    const active = [...this.transformers].reverse();
    return records.map((source) => {
      let current = clone(source);
      try {
        for (const transformer of active) current = clone(transformer.transform(clone(current)));
        return { ok: true, record: clone(current) };
      } catch (error: unknown) {
        return {
          ok: false,
          key: source.key,
          error: error instanceof Error ? error.message : String(error),
        };
      }
    });
  }
}

function clone(record: DataRecord): DataRecord {
  return { key: record.key, fields: { ...record.fields } };
}
```

