import { ConversionHub, type ConversionResult, type DataRecord, type Transformer } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function throwsKind(fn: () => unknown, kind: "TypeError" | "RangeError", message: string): void {
  try { fn(); } catch (error) {
    if ((kind === "TypeError" && error instanceof TypeError) || (kind === "RangeError" && error instanceof RangeError)) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

const empty = new ConversionHub();
equal(empty.convert([]), [], "empty conversion");
throwsKind(() => empty.register({ name: "   ", transform: (record) => record }), "TypeError", "blank name");
empty.register({ name: " trim-name ", transform: (record) => record });
throwsKind(() => empty.register({ name: "trim-name", transform: (record) => record }), "RangeError", "trimmed duplicate name");

const hub = new ConversionHub();
const calls: string[] = [];
const sharedOutput: DataRecord = { key: "shared", fields: { base: "yes" } };
const first: Transformer = {
  name: "first",
  transform(record) {
    calls.push(`first:${record.key}`);
    record.fields.first = "seen";
    sharedOutput.key = record.key;
    sharedOutput.fields = { ...record.fields };
    return sharedOutput;
  },
};
const second: Transformer = {
  name: "second",
  transform(record) {
    calls.push(`second:${record.key}`);
    record.fields.second = "seen";
    return record;
  },
};
hub.register(first);
hub.register(second);
const source: DataRecord = { key: "A", fields: { original: "value" } };
const converted = hub.convert([source]);
equal(calls, ["first:A", "second:A"], "registration order");
equal(converted, [{ ok: true, record: { key: "A", fields: { original: "value", first: "seen", second: "seen" } } }], "successful conversion");
equal(source, { key: "A", fields: { original: "value" } }, "source is not mutated");
equal(sharedOutput, { key: "A", fields: { original: "value", first: "seen" } }, "later transformer cannot mutate plugin output");
if (converted[0].ok) converted[0].record.fields.original = "changed";
equal(source.fields.original, "value", "returned record is detached from input");
equal(sharedOutput.fields.original, "value", "returned record is detached from plugin output");

const failureHub = new ConversionHub();
failureHub.register({ name: "mutate", transform(record) { record.key = `changed-${record.key}`; return record; } });
failureHub.register({ name: "fail-one", transform(record) { if (record.fields.fail === "yes") throw new Error("broken"); return record; } });
failureHub.register({ name: "after", transform(record) { record.fields.after = "yes"; return record; } });
const failureResults = failureHub.convert([
  { key: "one", fields: { fail: "yes" } },
  { key: "two", fields: { fail: "no" } },
]);
equal(failureResults, [
  { ok: false, key: "one", error: "broken" },
  { ok: true, record: { key: "changed-two", fields: { fail: "no", after: "yes" } } },
], "failure stops only one record and preserves input order");

const thrownValueHub = new ConversionHub();
thrownValueHub.register({ name: "throw-string", transform() { throw 42; } });
equal(thrownValueHub.convert([{ key: "k", fields: {} }]), [{ ok: false, key: "k", error: "42" }], "non-Error failures use String");

const snapshotHub = new ConversionHub();
let registered = false;
snapshotHub.register({
  name: "registrar",
  transform(record) {
    if (!registered) {
      registered = true;
      snapshotHub.register({ name: "late", transform(value) { value.fields.late = "yes"; return value; } });
    }
    return record;
  },
});
equal(snapshotHub.convert([{ key: "first", fields: {} }]), [{ ok: true, record: { key: "first", fields: {} } }], "registration does not affect active conversion");
equal(snapshotHub.convert([{ key: "later", fields: {} }]), [{ ok: true, record: { key: "later", fields: { late: "yes" } } }], "registration affects later conversions");

const twoResults: ConversionResult[] = hub.convert([{ key: "X", fields: {} }, { key: "Y", fields: {} }]);
if (twoResults[0].ok && twoResults[1].ok) {
  assert(twoResults[0].record !== twoResults[1].record && twoResults[0].record.fields !== twoResults[1].record.fields, "successful records are fresh copies");
}

